import numpy as np
def load(fn):
    with open(fn) as f: lines=f.read().splitlines()
    n=int(lines[0]); atoms=[]
    for l in lines[2:2+n]:
        p=l.split(); atoms.append((p[0],np.array([float(p[1]),float(p[2]),float(p[3])])))
    return atoms
atoms=load('complex_xtb_neutral.xyz')
n=len(atoms)
# bond graph by distance
def bondcut(e1,e2):
    if 'Ir' in (e1,e2): return 2.6
    if e1=='H' or e2=='H': return 1.3
    return 1.9
adj={i:[] for i in range(n)}
for i in range(n):
    for j in range(i+1,n):
        d=np.linalg.norm(atoms[i][1]-atoms[j][1])
        if d<bondcut(atoms[i][0],atoms[j][0]):
            adj[i].append(j); adj[j].append(i)
# check the two imidazole rings: find N atoms and their C neighbors
ns=[i for i,(e,p) in enumerate(atoms) if e=='N']
print("N atoms and neighbors:")
for i in ns:
    print(f"  N{i}: {[ (atoms[j][0]+str(j)) for j in adj[i]]}")
# carbene C: C bonded to 2 N
print("\nIr neighbors:")
irs=[i for i,(e,p) in enumerate(atoms) if e=='Ir']
for i in irs:
    print(f"  Ir{i}: {[(atoms[j][0]+str(j)) for j in adj[i]]}")
# Check COD rings: find C=C (dist ~1.34) among the cod carbons
# Identify fragments
def dfs(start,visited):
    stack=[start]; comp=[]
    while stack:
        x=stack.pop()
        if x in visited: continue
        visited.add(x); comp.append(x)
        for y in adj[x]:
            if y not in visited: stack.append(y)
    return comp
visited=set(); comps=[]
for i in range(n):
    if i not in visited:
        comps.append(dfs(i,visited))
print(f"\n{len(comps)} connected components, sizes:",[len(c) for c in comps])
